{"split":true,"newConcepts":[{"conceptId":"ce:PlanningActivity","block":"ce:PlanningActivity a tbox:ConceptualEntity ;
    rdfs:label "Planning activity"@en ;
    rdfs:comment "An engineering activity concerned with defining plans, processes, estimates, roadmaps, or anticipated resource needs."@en ;
    rdfs:subClassOf tbox:EngineeringActivity ;
    foaf:page <https://en.wikipedia.org/wiki/Software_project_management> ."},{"conceptId":"ce:ManagementActivity","block":"ce:ManagementActivity a tbox:ConceptualEntity ;
    rdfs:label "Management activity"@en ;
    rdfs:comment "An engineering activity concerned with managing project resources, risks, configuration, or stakeholders."@en ;
    rdfs:subClassOf tbox:EngineeringActivity ;
    foaf:page <https://en.wikipedia.org/wiki/Software_project_management> ."}],"assignments":[{"concept":"ce:ConfigurationManagementPlanning","property":"rdfs:subClassOf","assignedConceptId":"ce:ManagementActivity"},{"concept":"ce:EffortEstimation","property":"rdfs:subClassOf","assignedConceptId":"ce:PlanningActivity"},{"concept":"ce:ProcessDefinition","property":"rdfs:subClassOf","assignedConceptId":"ce:PlanningActivity"},{"concept":"ce:ProjectPlanning","property":"rdfs:subClassOf","assignedConceptId":"ce:PlanningActivity"},{"concept":"ce:ResourceAllocation","property":"rdfs:subClassOf","assignedConceptId":"ce:ManagementActivity"},{"concept":"ce:RiskManagement","property":"rdfs:subClassOf","assignedConceptId":"ce:ManagementActivity"},{"concept":"ce:Roadmapping","property":"rdfs:subClassOf","assignedConceptId":"ce:PlanningActivity"},{"concept":"ce:StakeholderManagement","property":"rdfs:subClassOf","assignedConceptId":"ce:ManagementActivity"}]}

{"split":true,"newConcepts":[{"conceptId":"ce:Backup","block":"ce:Backup a tbox:ConceptualEntity ;
    rdfs:label "Backup"@en ;
    rdfs:comment "An operations and maintenance activity that creates copies of data to enable restoration after data loss or corruption."@en ;
    rdfs:subClassOf ce:OperationsAndMaintenanceActivity ;
    foaf:page <https://en.wikipedia.org/wiki/Backup> ."},{"conceptId":"ce:Recovery","block":"ce:Recovery a tbox:ConceptualEntity ;
    rdfs:label "Data recovery"@en ;
    rdfs:comment "An operations and maintenance activity that restores or retrieves data after loss, corruption, or system failure."@en ;
    rdfs:subClassOf ce:OperationsAndMaintenanceActivity ;
    foaf:page <https://en.wikipedia.org/wiki/Data_recovery> ."}],"assignments":[]}

{"split":true,"newConcepts":[{"conceptId":"ce:OperationsActivity","block":"ce:OperationsActivity a tbox:ConceptualEntity ;
    rdfs:label "Operations activity"@en ;
    rdfs:comment "An engineering activity concerned with operating, administering, monitoring, and sustaining a software system in its deployment environment."@en ;
    rdfs:subClassOf tbox:EngineeringActivity ;
    foaf:page <https://en.wikipedia.org/wiki/Software_maintenance> ."},{"conceptId":"ce:MaintenanceActivity","block":"ce:MaintenanceActivity a tbox:ConceptualEntity ;
    rdfs:label "Maintenance activity"@en ;
    rdfs:comment "An engineering activity concerned with modifying, repairing, updating, or improving software after its initial delivery."@en ;
    rdfs:subClassOf tbox:EngineeringActivity ;
    foaf:page <https://en.wikipedia.org/wiki/Software_maintenance> ."}],"assignments":[{"concept":"ce:BackupAndRecovery","property":"rdfs:subClassOf","assignedConceptId":"ce:OperationsActivity"},{"concept":"ce:BugFixing","property":"rdfs:subClassOf","assignedConceptId":"ce:MaintenanceActivity"},{"concept":"ce:CapacityPlanning","property":"rdfs:subClassOf","assignedConceptId":"ce:OperationsActivity"},{"concept":"ce:IncidentManagement","property":"rdfs:subClassOf","assignedConceptId":"ce:OperationsActivity"},{"concept":"ce:Logging","property":"rdfs:subClassOf","assignedConceptId":"ce:OperationsActivity"},{"concept":"ce:Monitoring","property":"rdfs:subClassOf","assignedConceptId":"ce:OperationsActivity"},{"concept":"ce:Patching","property":"rdfs:subClassOf","assignedConceptId":"ce:MaintenanceActivity"},{"concept":"ce:PerformanceTuning","property":"rdfs:subClassOf","assignedConceptId":"ce:OperationsActivity"}]}

{"split":true,"newConcepts":[{"conceptId":"ce:QualityActivity","block":"ce:QualityActivity a tbox:ConceptualEntity ;
    rdfs:label "Quality activity"@en ;
    rdfs:comment "An engineering activity concerned with assuring, controlling, or improving software quality."@en ;
    rdfs:subClassOf tbox:EngineeringActivity ;
    foaf:page <https://en.wikipedia.org/wiki/Software_quality> ."},{"conceptId":"ce:GovernanceActivity","block":"ce:GovernanceActivity a tbox:ConceptualEntity ;
    rdfs:label "Governance activity"@en ;
    rdfs:comment "An engineering activity concerned with organizational oversight, compliance, accountability, security management, or related governance practices."@en ;
    rdfs:subClassOf tbox:EngineeringActivity ;
    foaf:page <https://en.wikipedia.org/wiki/Software_quality> ."}],"assignments":[{"concept":"ce:Auditing","property":"rdfs:subClassOf","assignedConceptId":"ce:GovernanceActivity"},{"concept":"ce:ComplianceManagement","property":"rdfs:subClassOf","assignedConceptId":"ce:GovernanceActivity"},{"concept":"ce:Documentation","property":"rdfs:subClassOf","assignedConceptId":"ce:GovernanceActivity"},{"concept":"ce:QualityAssurance","property":"rdfs:subClassOf","assignedConceptId":"ce:QualityActivity"},{"concept":"ce:QualityControl","property":"rdfs:subClassOf","assignedConceptId":"ce:QualityActivity"},{"concept":"ce:SecurityManagement","property":"rdfs:subClassOf","assignedConceptId":"ce:GovernanceActivity"}]}

{"split":true,"newConcepts":[{"conceptId":"ce:ReleaseActivity","block":"ce:ReleaseActivity a tbox:ConceptualEntity ;
    rdfs:label "Release activity"@en ;
    rdfs:comment "An engineering activity concerned with preparing, managing, versioning, packaging, or making a software release available."@en ;
    rdfs:subClassOf tbox:EngineeringActivity ;
    foaf:page <https://en.wikipedia.org/wiki/Software_release_life_cycle> ."},{"conceptId":"ce:DeploymentActivity","block":"ce:DeploymentActivity a tbox:ConceptualEntity ;
    rdfs:label "Deployment activity"@en ;
    rdfs:comment "An engineering activity concerned with deploying software to an environment, continuously deploying it, or managing deployment rollback."@en ;
    rdfs:subClassOf tbox:EngineeringActivity ;
    foaf:page <https://en.wikipedia.org/wiki/Software_release_life_cycle> ."}],"assignments":[{"concept":"ce:ContinuousDelivery","property":"rdfs:subClassOf","assignedConceptId":"ce:ReleaseActivity"},{"concept":"ce:ContinuousDeployment","property":"rdfs:subClassOf","assignedConceptId":"ce:DeploymentActivity"},{"concept":"ce:ContinuousIntegration","property":"rdfs:subClassOf","assignedConceptId":"ce:ReleaseActivity"},{"concept":"ce:Deployment","property":"rdfs:subClassOf","assignedConceptId":"ce:DeploymentActivity"},{"concept":"ce:Packaging","property":"rdfs:subClassOf","assignedConceptId":"ce:ReleaseActivity"},{"concept":"ce:ReleaseManagement","property":"rdfs:subClassOf","assignedConceptId":"ce:ReleaseActivity"},{"concept":"ce:RollbackManagement","property":"rdfs:subClassOf","assignedConceptId":"ce:DeploymentActivity"},{"concept":"ce:Versioning","property":"rdfs:subClassOf","assignedConceptId":"ce:ReleaseActivity"}]}

{"split":true,"newConcepts":[{"conceptId":"ce:Training","block":"ce:Training a tbox:ConceptualEntity ;
    rdfs:label "Training"@en ;
    rdfs:comment "A support activity that provides instruction and develops the knowledge or skills needed to use a language, tool, or related practice."@en ;
    rdfs:subClassOf ce:SupportActivity ."},{"conceptId":"ce:Onboarding","block":"ce:Onboarding a tbox:ConceptualEntity ;
    rdfs:label "Onboarding"@en ;
    rdfs:comment "A support activity that introduces and integrates a person into a project, organization, tool environment, or working practice."@en ;
    rdfs:subClassOf ce:SupportActivity ;
    foaf:page <https://en.wikipedia.org/wiki/Onboarding> ."}],"assignments":[]}
